         linear_row < total_rows;
         linear_row += static_cast<int>(gridDim.x) * 16) {
        const int row = linear_row % n;
        const long long base = static_cast<long long>(linear_row) * n;
        const int aligned_col = (row + 3) & ~3;
        const int scalar_stop = aligned_col < n ? aligned_col : n;
        for (int col = row + lane; col < scalar_stop; col += 32) {
            output[base + col] = input[base + col];
