__global__ void grouped_upper_copy_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    int n,
    int batch
) {
    const int total_rows = batch * n;
    const int warp = static_cast<int>(threadIdx.x) >> 5;
    const int lane = static_cast<int>(threadIdx.x) & 31;
    for (int linear_row = static_cast<int>(blockIdx.x) * 8 + warp;
         linear_row < total_rows;
         linear_row += static_cast<int>(gridDim.x) * 8) {
        const int row = linear_row % n;
        const long long base = static_cast<long long>(linear_row) * n;
        const int aligned_col = (row + 3) & ~3;
        const int scalar_stop = aligned_col < n ? aligned_col : n;
        for (int col = row + lane; col < scalar_stop; col += 32) {
            output[base + col] = input[base + col];
        }
        const int first_vector = aligned_col / 4;
        const int vector_count = n / 4;
        const float4* input_vectors = reinterpret_cast<const float4*>(
            input + base
        );
        float4* output_vectors = reinterpret_cast<float4*>(output + base);
        for (int vector = first_vector + lane;
             vector < vector_count; vector += 32) {
            output_vectors[vector] = input_vectors[vector];
        }
    }
}

void grouped_upper_copy_cuda(
        torch::Tensor input, torch::Tensor output) {
    TORCH_CHECK(input.is_cuda() && output.is_cuda(), "CUDA tensors required");
    TORCH_CHECK(
        input.scalar_type() == torch::kFloat32
        && output.scalar_type() == torch::kFloat32,
        "FP32 tensors required"
    );
    TORCH_CHECK(
        input.dim() == 3 && input.size(1) == input.size(2)
        && input.is_contiguous() && output.is_contiguous()
        && input.sizes() == output.sizes(),
        "matching contiguous batched square matrices required"
    );
    const int n = static_cast<int>(input.size(1));
    const int batch = static_cast<int>(input.size(0));
    TORCH_CHECK((n & 3) == 0, "matrix width must be float4 aligned");
    const int rows = batch * n;
    const int row_groups = (rows + 15) / 16;
    const int blocks = row_groups < 1024 ? row_groups : 1024;
    grouped_upper_copy_kernel<<<
        blocks, 512, 0,
        c10::cuda::AC_CAT(getCurrentCUDA, AC_CAT(Str, eam))()
    >>>(
        input.data_ptr<float>(), output.data_ptr<float>(), n, batch
    );
    C10_CUDA_KERNEL_LAUNCH_CHECK();
}

